/* From Uiverse.io by mi-series - Tags: simple, material design, pricing, green, minimalist, card, chatgpt */
.__UIV_SCOPE__ .container {
  width: 300px;
  padding: 15px;
  background: #ffffff;
  text-align: center;
  border: 1px solid #000;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 0 15px rgba(0, 0, 0, 0.05);
  position: relative;
}

.__UIV_SCOPE__ .container .title {
  font-size: 2rem;
  font-weight: 500;
  color: #333;
}

.__UIV_SCOPE__ .container .price {
  color: #40B3A2;
  font-weight: 700;
  font-size: 2.2rem;
  margin: 10px 0;
}

.__UIV_SCOPE__ .container span {
  font-size: 1.2rem;
}

.__UIV_SCOPE__ .container .description {
  color: #3b3b3b;
  font-size: 1.1rem;
  margin: 10px 0 10px;
}

.__UIV_SCOPE__ .container .offer {
  display: block;
  color: #555;
  font-size: 1rem;
  margin-top: 10px;
}

.__UIV_SCOPE__ .subscribe-button {
  display: inline-block;
  padding: 5px 0;
  background-color: #40B3A2;
  color: #fff;
  text-decoration: none;
  border: 1px solid #000;
  border-radius: 30px;
  font-size: 1.2rem;
  margin-top: 20px;
  width: 50%;
  font-weight: 500;
  transition: 0.2s ease;
}

.__UIV_SCOPE__ .subscribe-button:hover {
  opacity: .85;
}

.__UIV_SCOPE__ .ribbon-wrap {
  width: 80px;
  height: 80px;
  position: absolute;
  top: -20px;
  left: 50px;
  pointer-events: none;
}

.__UIV_SCOPE__ .ribbon {
  width: 200px;
  font-size: 0.8rem;
  text-align: center;
  padding: 4px 0;
  border: 1px solid #000;
  background: #40B3A2;
  color: #fff;
  position: absolute;
  transform: rotate(-45deg);
  right: -10px;
  top: 55%;
}
